 const fetchText=async file=>{try{const r=await fetch('./'+file+'?diag='+Date.now(),{cache:'no-store'});return r.ok?await r.text():'HTTP '+r.status}catch{return 'Unavailable'}};const [indexText,appText,checkText,swText,versionText]=await Promise.all(['index.html','app.js','inline-check.js','sw.js','version.json'].map(fetchText));const getBuild=t=>{const m=t.match(/TT-20\d\d\.\d\d\.\d\d-r\d+/);return m?m[0]:(t.startsWith('HTTP ')||t==='Unavailable'?'Unavailable':'Build marker missing')};let ver='Unavailable';try{ver=JSON.parse(versionText).build||'Build marker missing'}catch{}const host=$('modalContent');if(!host||!host.closest('.modal'))return;host.innerHTML=`<div class="stack"><p><b>Running app build:</b> ${BUILD_ID}</p><p><b>index.html fetched from GitHub Pages:</b> ${esc(getBuild(indexText))}</p><p><b>app.js fetched:</b> ${esc(getBuild(appText))}</p><p><b>inline-check.js fetched:</b> ${esc(getBuild(checkText))}</p><p><b>sw.js fetched:</b> ${esc((swText.match(/touchline-tracker-[^'\"]+/)||[])[0]||'Cache marker missing')}</p><p><b>version.json fetched:</b> ${esc(ver)}</p><p><b>Service worker controller:</b> ${esc(sw)}</p><p><b>Cache names:</b> ${esc(cacheNames)}</p><p><b>IndexedDB:</b> ${esc(idb)}</p><p><b>Saved teams:</b> ${(data.settings?.teams||[]).length}</p><p><b>Squad players:</b> ${(data.squad||[]).length}</p><p><b>Saved matches:</b> ${(data.matches||[]).length}</p><p><b>Current events:</b> ${(m().events||[]).length}</p><p><b>Persistence:</b> IndexedDB mirror + localStorage compatibility</p><p class="muted">For a consistent upload, all fetched build markers should be TT-2026.10.18-r24.</p><button class="primary" id="diagReload" type="button">Reload latest version</button></div>`;
