if(!data.match.venueType)data.match.venueType='Home';if(!data.match.matchType)data.match.matchType='League';if(!data.match.opponentColours)data.match.opponentColours='Black';if(!data.match.tournamentGroup)data.match.tournamentGroup='';if(!data.match.startingPlayers)data.match.startingPlayers=[];if(!data.match.activePlayers)data.match.activePlayers=[];if(!data.match.substitutes)data.match.substitutes=[];
