function m(){return data.match}
function matchHasContent(match=m()){return !!(match&&((Array.isArray(match.events)&&match.events.length>0)||String(match.team||'').trim()||((match.status||'ready')!=='ready')||(match.shootout&&((match.shootout.our||[]).length||(match.shootout.opp||[]).length))))}
function elapsed(){return (m().elapsedMs||0)+(m().runningSince?Date.now()-m().runningSince:0)}
function fmt(ms){let s=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function stamp(){return fmt(elapsed())}
function periodElapsed(){const now=elapsed(),base=Number(m().periodStartedElapsedMs||0);return Math.max(0,now-base)}
function periodStamp(){return '['+fmt(periodElapsed())+']'}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(){return crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(16).slice(2)}
const MAX_UNDO_ENTRIES=12, MAX_UNDO_BYTES=320*1024;
function trimUndo(){const undo=m().undo||(m().undo=[]);while(undo.length>MAX_UNDO_ENTRIES)undo.shift();let bytes=undo.reduce((n,x)=>n+String(x).length,0);while(undo.length&&bytes>MAX_UNDO_BYTES){bytes-=String(undo.shift()).length}}
