function persistData(){const status=$('saveStatus');try{trimUndo();data.storageUpdatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(data));idbPut(JSON.parse(JSON.stringify(data))).then(ok=>{if(!ok&&status)status.textContent='Saved on device · IndexedDB backup unavailable'});if(status){status.textContent='Saved on device';status.classList.add('safe')}return true}catch(e){/* Free undo history before declaring storage exhausted. */try{(data.match.undo||[]).length=0;localStorage.setItem(KEY,JSON.stringify(data));if(status){status.textContent='Saved on device · older undo history cleared to free storage';status.classList.add('safe')}return true}catch(e2){if(status){status.textContent='Storage full — export a backup and remove old saved matches';status.classList.remove('safe')}return false}}}
