function openModal(title,content){$('modalRoot').innerHTML=`<div class="modalback" id="modalBack"><div class="modal"><button type="button" class="neutral small modalclose" id="modalClose">Close</button><h2>${esc(title)}</h2><div id="modalContent">${content}</div></div></div>`;$('modalClose').onclick=closeModal;$('modalBack').onclick=e=>{if(e.target.id==='modalBack')closeModal()}}
