async function clearAllAppStorage(){
 resetInProgress=true;
 try{
  if('indexedDB' in window){
   const db=await openAppDB();
   if(db){await new Promise(resolve=>{let tx;try{const names=Array.from(db.objectStoreNames);if(!names.length){db.close();resolve();return}tx=db.transaction(names,'readwrite');names.forEach(name=>tx.objectStore(name).clear());tx.oncomplete=()=>{try{db.close()}catch{}resolve()};tx.onerror=()=>{try{db.close()}catch{}resolve()};tx.onabort=()=>{try{db.close()}catch{}resolve()}}catch{try{db.close()}catch{}resolve()}})}
  }
 }catch(err){console.warn('IndexedDB reset cleanup issue',err)}
 try{for(const key of Object.keys(localStorage)){if(key===KEY||key.startsWith('touchline-'))localStorage.removeItem(key)}}catch{}
}
function showFactoryResetWarning(){openModal('Factory reset — permanently delete everything',`<div class="notice"><strong>Warning: this cannot be undone.</strong><p>This will permanently delete all Touchline Tracker data saved on this device, including your squad and saved teams, match history and statistics, current match and penalty shootout, player settings, event button settings, clubs, kit colours, seasons and competitions. It clears both localStorage and the app's IndexedDB records.</p><p>It will not delete backup files you have already exported elsewhere. Export a backup first if you may want to keep anything.</p></div><label style="display:flex;gap:9px;align-items:flex-start;margin:12px 0"><input id="factoryResetAcknowledged" type="checkbox" style="margin-top:4px;transform:scale(1.15)"><span>I understand that all Touchline Tracker data and settings on this device will be permanently deleted.</span></label><button class="danger" id="confirmFactoryResetBtn" type="button" disabled style="width:100%">Permanently reset app</button><button class="neutral" id="cancelFactoryResetBtn" type="button" style="width:100%;margin-top:8px">Cancel</button>`);$('factoryResetAcknowledged').onchange=()=>{$('confirmFactoryResetBtn').disabled=!$('factoryResetAcknowledged').checked};$('cancelFactoryResetBtn').onclick=closeModal;$('confirmFactoryResetBtn').onclick=async()=>{if(!$('factoryResetAcknowledged').checked)return;const b=$('confirmFactoryResetBtn');b.disabled=true;b.textContent='Deleting saved data…';await clearAllAppStorage();closeModal();location.replace(location.pathname+location.search+'#reset');location.replace(location.pathname+'?ttv='+Date.now())}}
function recordAssist(p){const latest=goals().slice().reverse().find(g=>!g.assistId);if(latest){assignAssist(latest.id,p);return}const gs=goals().filter(g=>!g.assistId);if(!gs.length){const all=goals();if(!all.length)return alert('Record a goal first.');openModal('Choose a goal to update',all.map(g=>`<button class="goalpick" data-assist-goal="${g.id}"><strong>${esc(g.at)} · ${esc(g.scorerName)}</strong><span class="muted">${esc(g.period)} · ${g.assistName?'Assist: '+esc(g.assistName):'No assist yet'}</span></button>`).join(''));pendingAssistPlayer=p;return}openModal('Which goal did '+p.name+' assist?',gs.map(g=>`<button class="goalpick" data-assist-goal="${g.id}"><strong>${esc(g.at)} · ${esc(g.scorerName)}</strong><span class="muted">${esc(g.period)} · ${esc(g.assistName||'No assist yet')}</span></button>`).join('')+`<p class="muted">Goals already assigned an assist are hidden. To change one, use Edit on the timeline.</p>`);pendingAssistPlayer=p}
