function formatPeriods(){return m().format==='halves'?[{label:'1st half',start:'Start 1st half',end:'End 1st half'},{label:'2nd half',start:'Start 2nd half',end:'End 2nd half'}]:[{label:'Q1',start:'Start Q1',end:'End Q1'},{label:'Q2',start:'Start Q2',end:'End Q2'},{label:'Q3',start:'Start Q3',end:'End Q3'},{label:'Q4',start:'Start Q4',end:'End Q4'}]}
