function archiveFinishedMatch(){if(!matchHasContent())return false;(m().injuredPlayers||[]).forEach(id=>{const p=data.squad.find(x=>x.id===id);if(p)p.injured=true});m().historySaved=true;const snapshotMatch=JSON.parse(JSON.stringify({...m(),historyKeyWasAssigned:undefined,shootout:m().shootout?JSON.parse(JSON.stringify(m().shootout)):null,squadSnapshot:data.squad.map(p=>({id:p.id,name:p.name,shirtNumbers:p.shirtNumbers||{}})),teamKitsSnapshot:JSON.parse(JSON.stringify(data.settings.teamKits||[]))}));m().historyKeyWasAssigned=!!m().historyKey;const key=m().historyKey||(m().historyKey=uid());snapshotMatch.historyKey=key;const record={historyKey:key,team:m().team,opponent:m().opponent,date:m().date,format:m().format,goals:ourGoals(),opponentGoals:oppGoals(),shootout:snapshotMatch.shootout,penaltyScore:shootoutScoreFor(snapshotMatch),match:snapshotMatch};const i=data.matches.findIndex(r=>r.historyKey===key||(r.match&&r.match.historyKey===key)||(!m().historyKeyWasAssigned&&((r.match||r).date===m().date)&&((r.match||r).team||'')===(m().team||'')&&((r.match||r).opponent||'')===(m().opponent||'')&&JSON.stringify(((r.match||r).events)||[])===JSON.stringify(m().events||[])));if(i>=0)data.matches[i]=record;else data.matches.push(record);return true}
function openPlayerOfMatchPicker(){const all=(m().squadSnapshot&&m().squadSnapshot.length?m().squadSnapshot:data.squad)||[];const current=m().playerOfTheMatch?.playerId||'';const starters=new Set(m().startingPlayers||[]),subs=new Set(m().substitutes||[]);const groups=[['Starting players',all.filter(p=>starters.has(p.id))],['Substitutes',all.filter(p=>subs.has(p.id)||(!starters.has(p.id)&&!((m().activePlayers||[]).includes(p.id))))],['Other squad players',all.filter(p=>!starters.has(p.id)&&!subs.has(p.id)&&(m().activePlayers||[]).includes(p.id))]];const option=(p)=>`<button class="goalpick ${p.id===current?'selected':''}" data-select-potm="${esc(p.id)}">${esc(p.name)}${p.id===current?' ✓':''}</button>`;const groupsHtml=groups.filter(g=>g[1].length).map(g=>`<h3>${g[0]}</h3><div class="stack">${g[1].map(option).join('')}</div>`).join('');openModal('Choose player of the match',`<p class="muted">Choose a player, including a substitute, or select None.</p><button class="goalpick ${!current?'selected':''}" data-select-potm="">None${!current?' ✓':''}</button>${groupsHtml}<button class="neutral" id="cancelPotmBtn" type="button" style="width:100%;margin-top:8px">Cancel</button>`);const saveChoice=(id)=>{const p=all.find(x=>x.id===id);m().events=(m().events||[]).filter(e=>e.type!=='playerOfTheMatch');m().playerOfTheMatch=p?{playerId:p.id,playerName:p.name}:null;if(p)m().events.push({id:uid(),type:'playerOfTheMatch',playerId:p.id,playerName:p.name,text:'Player of the Match: '+p.name,at:stamp(),period:'Full time'});if(m().status==='finished')archiveFinishedMatch();save();closeModal();render()};document.querySelectorAll('[data-select-potm]').forEach(b=>b.onclick=()=>saveChoice(b.getAttribute('data-select-potm')||''));const cancel=$('cancelPotmBtn');if(cancel)cancel.onclick=closeModal} 
