function eventLabel(type){const defaults={goal:'Goal',assist:'Assist',shot:'Shot',save:'Save',corner:'Corner',freeKick:'Free kick',penalty:'Penalty',fouled:'Fouled',throwIn:'Kick/Throw-in',redCard:'Red card',yellowCard:'Yellow card',injured:'Injured / Fit again'};return data.settings?.eventNames?.[type]||data.settings?.extraEvents?.find(x=>x.key===type)?.label||defaults[type]||type}
function recordPlayerEvent(p,type){if(type==='injured'){if(m().status==='finished')return alert('This match is finished. Start a new match to record more events.');m().injuredPlayers=m().injuredPlayers||[];const injured=m().injuredPlayers.includes(p.id);snapshot();m().injuredPlayers=injured?m().injuredPlayers.filter(id=>id!==p.id):[...m().injuredPlayers,p.id];p.injured=!injured;m().events.push({id:uid(),at:stamp(),period:m().period,type:'injury',playerId:p.id,playerName:p.name,text:injured?`${p.name} marked fit during match`:`${p.name} injured`});if(!injured)p.injured=true;save();return}if(m().status==='finished')return alert('This match is finished. Start a new match to record more events.');if(type==='goal')return recordGoal(p);if(type==='assist')return recordAssist(p);if(type==='shot')return openOutcomeChoice(p,'shot');if(type==='penalty'||type==='freeKick')return openOutcomeChoice(p,type);if(type==='save')return addEvent({type:'save',playerId:p.id,playerName:p.name,text:'Save'});addEvent({type,playerId:p.id,playerName:p.name,text:eventLabel(type)});if(type==='redCard'){m().activePlayers=(m().activePlayers.length?m().activePlayers:m().startingPlayers).filter(id=>id!==p.id);m().redCarded=[...new Set([...(m().redCarded||[]),p.id])];save()}}
function openOutcomeChoice(p,kind){const label=eventLabel(kind);openModal(label+' outcome · '+p.name,`<div class="stack"><button type="button" class="green" data-outcome="saved" data-outcomekind="${kind}" data-shotplayer="${p.id}">🧤 ${kind==='shot'?'Shot saved':'Saved / stopped'}</button><button type="button" class="neutral" data-outcome="post" data-outcomekind="${kind}" data-shotplayer="${p.id}">Hits post</button><button type="button" class="neutral" data-outcome="crossbar" data-outcomekind="${kind}" data-shotplayer="${p.id}">Hits crossbar</button><button type="button" class="neutral" data-outcome="offtarget" data-outcomekind="${kind}" data-shotplayer="${p.id}">Off target / wide</button><button type="button" class="primary" data-outcome="goal" data-outcomekind="${kind}" data-shotplayer="${p.id}">⚽ Goal scored</button></div>`);document.querySelectorAll('[data-outcome]').forEach(btn=>btn.onclick=(clickEvent)=>{clickEvent.stopPropagation();const outcome=btn.dataset.outcome,evKind=btn.dataset.outcomekind,player=data.squad.find(x=>x.id===btn.dataset.shotplayer);if(!player)return;if(outcome==='goal'){if(evKind!=='shot')addEvent({type:evKind+'_goal',playerId:player.id,playerName:player.name,text:`${eventLabel(evKind)}: goal scored`,outcome});addEvent({type:'goal',playerId:player.id,scorerName:player.name,playerName:player.name,text:evKind==='shot'?'Goal from shot':`Goal from ${eventLabel(evKind).toLowerCase()}`,assistId:null,assistName:null,sourceType:evKind})}else addEvent({type:evKind+'_'+outcome,playerId:player.id,playerName:player.name,text:`${eventLabel(evKind)}: ${{saved:'saved/stopped',post:'hits post',crossbar:'hits crossbar',offtarget:'off target'}[outcome]}`,outcome});closeModal()})}
function renderEventTotals(){let counts={};m().events.forEach(e=>{if(!['period','periodEnd','opponentGoal','goal'].includes(e.type))counts[e.text||eventLabel(e.type)||e.type]=(counts[e.text||eventLabel(e.type)||e.type]||0)+1});let goalCount=ourGoals(),opp=oppGoals();$('eventTotals').innerHTML=`<div class="summaryline row between"><span>Goals</span><strong>${goalCount}</strong></div><div class="summaryline row between"><span>Opposition goals</span><strong>${opp}</strong></div>`+Object.entries(counts).map(([k,v])=>`<div class="summaryline row between"><span>${esc(k)}</span><strong>${v}</strong></div>`).join('')}
function renderTeamChoices(){let sel=$('teamName');if(!sel)return;let old=m().team||'';let names=[...new Set([...(data.settings.teams||[]).map(t=>t.name),old].filter(Boolean))];sel.innerHTML='<option value="">Choose your team…</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');sel.value=names.includes(old)?old:''}
let teamDirty=false;
function markTeamDirty(){teamDirty=true;const n=$('teamDirtyNotice');if(n)n.classList.remove('hidden');}
function clearTeamDirty(){teamDirty=false;const n=$('teamDirtyNotice');if(n)n.classList.add('hidden');}
function persistCurrentTeamEdits(){
 const name=($('squadTeamName')?.value||m().team||'').trim();
 if(!name||!data.squad.length){alert('Enter a team name and add at least one player before saving.');return false;}
 data.settings.teams=data.settings.teams||[];
 const current=data.settings.teams.find(t=>t.name===m().team);
 const duplicate=data.settings.teams.find(t=>t.name.toLowerCase()===name.toLowerCase()&&t!==current);
 if(duplicate){alert('A team with that name already exists. Choose it from Saved teams instead.');return false;}
 const record=current||{name,players:[],kits:[]};
 record.name=name;record.players=JSON.parse(JSON.stringify(data.squad));record.kits=JSON.parse(JSON.stringify(data.settings.teamKits||[]));record.ageGroup=m().ageGroup||record.ageGroup||'';
 if(!current)data.settings.teams.push(record);
 m().team=name;renderSavedTeamSelect();renderBackupChoices();clearTeamDirty();save();return true;
}
function confirmTeamSwitch(){
 if(!teamDirty)return true;
 if(confirm('This team has unsaved changes. Press OK to save them before switching, or Cancel to choose whether to discard them.'))return persistCurrentTeamEdits();
 if(!confirm('Discard the unsaved player and kit changes and continue?'))return false;
 clearTeamDirty();return true;
}
function renderSavedTeamSelect(){const sel=$('savedTeamSelect');if(!sel)return;const old=sel.value;sel.innerHTML='<option value="">Choose a saved team…</option>'+(data.settings.teams||[]).map(t=>`<option value="${esc(t.name)}">${esc(t.name)}</option>`).join('');sel.value=(data.settings.teams||[]).some(t=>t.name===(old||m().team))?(old||m().team):'';}
