function renderMatchChoices(){let sel=$('opponent');if(!sel)return;let old=sel.value||m().opponent||'';let names=[...new Set([...(data.settings.clubs||[]),...data.matches.map(r=>(r.match||r).opponent).filter(Boolean),m().opponent].filter(Boolean))];sel.innerHTML='<option value="">Choose opposition…</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');sel.value=names.includes(old)?old:'';let mt=$('matchType'),prior=m().matchType||'League';mt.innerHTML=(data.settings.competitionTypes||['League','Cup','Friendly','Tournament']).map(n=>`<option>${esc(n)}</option>`).join('');if(!(data.settings.competitionTypes||[]).includes(prior))prior=(data.settings.competitionTypes||['League'])[0];mt.value=prior;let kit=$('opponentColours'),oldKit=m().opponentColours||'Black';kit.innerHTML=[...new Set(['Black','White','Blue','Red','Yellow','Green','Orange',...(data.settings.teamKits||[]).map(k=>k.colour),...(data.settings.kitColours||[]),oldKit])].map(n=>`<option>${esc(n)}</option>`).join('');kit.value=oldKit;let own=$('teamColours'),oldOwn=m().teamColours||'';const ownColours=[...new Set((data.settings.teamKits||[]).map(k=>String(k.colour||'').trim()).filter(Boolean))];own.innerHTML=ownColours.length?ownColours.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join(''):'<option value="">Load a saved team first</option>';if(ownColours.includes(oldOwn))own.value=oldOwn;else{const venueKit=ownColours.find((_,i)=>{const k=data.settings.teamKits.filter(x=>String(x.colour||'').trim());return k[i]&&k[i].name===(m().venueType==='Away'?'Away':'Home')});own.value=venueKit||ownColours[0]||'';m().teamColours=own.value}renderSavedTeamSelect()}
function renderClubSettings(){let el=$('clubSettings');if(!el)return;el.innerHTML=`<div class="summaryline"><strong>Opposition clubs</strong>${(data.settings.clubs||[]).map((c,i)=>`<div class="row between"><span>${esc(c)}</span><div><button class="neutral small" data-edit-club="${i}">Edit</button> <button class="danger small" data-delete-club="${i}">Delete</button></div></div>`).join('')||'<p class="muted">No saved clubs yet. Use ＋ beside Opposition to add one.</p>'}</div><div class="summaryline"><strong>Kit colours</strong><div class="stack">${(data.settings.kitColours||[]).map((c,i)=>`<div class="row between"><span>${esc(c)}</span><div><button class="neutral small" data-move-kit="${i}" data-dir="-1">↑</button> <button class="neutral small" data-move-kit="${i}" data-dir="1">↓</button> <button class="neutral small" data-edit-kit="${i}">Edit</button> <button class="danger small" data-delete-kit="${i}">Delete</button></div></div>`).join()}</div><button class="neutral small" id="addKitSettingBtn">＋ Add kit colour</button></div><div class="summaryline"><strong>Competition types</strong>${(data.settings.competitionTypes||[]).map((c,i)=>`<div class="row between"><span>${esc(c)}</span><div><button class="neutral small" data-move-competition="${i}" data-dir="-1">↑</button> <button class="neutral small" data-move-competition="${i}" data-dir="1">↓</button> <button class="danger small" data-delete-competition="${i}">Delete</button></div></div>`).join('')}</div>`;let ss=$('seasonSettings');ss.innerHTML=(data.settings.seasons||[]).map((x,i)=>`<div class="summaryline row between"><span>${esc(x.name)} · ${esc(x.start||'')} to ${esc(x.end||'')}</span><div><button class="neutral small" data-edit-season="${i}">Edit</button> <button class="danger small" data-delete-season="${i}">Delete</button></div></div>`).join('')||'<p class="muted">No custom seasons saved.</p>';renderSavedTeamSelect();if($('layoutMode'))$('layoutMode').value=data.settings.layoutMode||'cards'}
function renderBackupChoices(){const team=$('teamBackupSelect');if(team){const old=team.value||'all';const names=[...new Set([...(data.settings.teams||[]).map(t=>t.name),m().team].filter(Boolean))];team.innerHTML='<option value="all">All teams</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');team.value=names.includes(old)?old:'all'}const seasons=[...(data.settings.seasons||[]).map(x=>x.name),...data.matches.map(r=>(r.match||r).season).filter(Boolean)];const ss=$('backupSeasonSelect');if(ss){const old=ss.value;ss.innerHTML='<option value="">Choose season…</option>'+[...new Set(seasons)].map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');ss.value=old}const tours=[...data.matches.map(r=>(r.match||r).tournamentGroup).filter(Boolean),m().tournamentGroup].filter(Boolean);const ts=$('backupTournamentSelect');if(ts){const old=ts.value;ts.innerHTML='<option value="">Choose tournament…</option>'+[...new Set(tours)].map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');ts.value=old}}
function renderSettings(){renderBackupChoices();renderClubSettings();let types=[['goal','Goal'],['assist','Assist'],['shot','Shot'],['save','Save'],['corner','Corner'],['freeKick','Free kick'],['penalty','Penalty'],['fouled','Fouled'],['throwIn','Kick/Throw-in'],['redCard','Red card'],['yellowCard','Yellow card'],['injured','Injured / Fit again']];const built=types.map(([k,l])=>`<div class="summaryline"><label class="label">${esc(l)} label</label><input class="field setting-label" data-setting-label="${k}" value="${esc(eventLabel(k))}"><div class="row" style="margin-top:6px"><label class="muted">Button order</label><input class="field setting-order" data-setting-order="${k}" type="number" min="1" max="30" value="${(data.settings.buttonOrder||[]).indexOf(k)+1||''}" placeholder="hidden from main row"></div></div>`).join('');const custom=(data.settings.extraEvents||[]).map((x,i)=>`<div class="summaryline"><label class="label">Custom event</label><input class="field" data-custom-event-label="${esc(x.key)}" value="${esc(x.label||x.key)}" aria-label="Custom event label"><div class="row" style="margin-top:6px;gap:8px"><label class="muted">Button order</label><input class="field setting-order" data-setting-order="${esc(x.key)}" type="number" min="1" max="30" value="${(data.settings.buttonOrder||[]).indexOf(x.key)+1||''}" placeholder="not on main row"><button class="danger small" data-delete-custom-event="${esc(x.key)}" type="button">Delete</button></div></div>`).join('');$('settingsEvents').innerHTML=built+(custom?`<h3 style="margin:12px 0 6px">Custom event buttons</h3>${custom}`:'<p class="muted">No custom event buttons added.</p>')+`<div class="summaryline"><label class="label">Custom player positions</label><div class="stack">${(data.settings.extraPositions||[]).map((pos,i)=>`<div class="row between"><span>${esc(pos)}</span><button class="danger small" data-delete-position="${i}">Delete</button></div>`).join('')||'<div class="muted">None added</div>'}</div><button class="neutral small" id="addPositionBtn">＋ Add position</button></div><div class="summaryline"><label class="label">Default match setup</label><p class="muted">New matches default to 7-a-side with a 2-3-1 formation. Change player count and formation on the match screen.</p></div>`}
function kitColourForPitch(){return String(m().teamColours||'Blue').toLowerCase()}
function builtinFormationRows(n){return ({5:[[1,2,1],[2,1,1],[1,1,2]],6:[[2,2,1],[1,2,2],[2,1,2]],7:[[2,3,1],[3,2,1],[2,2,2],[1,2,3],[1,2,2,1],[2,1,2,1]],8:[[3,2,2],[2,3,2],[2,2,2,1]],9:[[3,3,2],[2,3,3],[3,2,2,1]],10:[[3,3,3],[4,3,2],[3,4,2]],11:[[4,3,3],[4,4,2],[3,5,2],[4,2,3,1],[3,4,3],[5,3,2]]})[n]||[]}
function formationList(n){const built=builtinFormationRows(n).map(rows=>({name:rows.join('-'),rows,players:n,custom:false}));const custom=(data.settings.formations||[]).filter(f=>Number(f.players)===n).map(f=>({name:f.name,rows:f.rows||String(f.name).split('-').map(Number),players:n,custom:true}));const all=[...built,...custom];return all.filter((f,i,a)=>f.rows.reduce((x,y)=>x+y,0)===n-1&&a.findIndex(x=>x.name.toLowerCase()===f.name.toLowerCase())===i)}
function renderFormationChoices(){const sel=$('formation');if(!sel)return;const n=Number($('playersPerSide')?.value||m().playersPerSide||7),old=m().formation||'2-3-1',list=formationList(n);sel.innerHTML=list.map(f=>`<option value="${esc(f.name)}">${esc(f.name)}</option>`).join('');sel.value=list.some(f=>f.name===old)?old:(list[0]?.name||'');m().formation=sel.value}
function manageFormations(){const n=Number(m().playersPerSide||7);const items=(data.settings.formations||[]).map((f,i)=>`<div class="summaryline"><div class="row between"><div><strong>${esc(f.rows.join('-'))}</strong><div class="muted">${f.players}-a-side · ${esc(f.rows.join('-'))}</div></div><div><button class="neutral small" data-edit-formation="${i}">Edit</button> <button class="danger small" data-delete-formation="${i}">Delete</button></div></div></div>`).join('');openModal('Manage formations',`<p class="muted">Enter the number of outfield players in each row, nearest your own goal first. The goalkeeper is added automatically. Row counts must total one fewer than players per side.</p><div class="summaryline"><label class="label" for="formationPlayerCount">Players per side</label><select id="formationPlayerCount" class="field">${[5,6,7,8,9,10,11].map(v=>`<option value="${v}" ${v===n?'selected':''}>${v}-a-side (${v-1} outfield)</option>`).join('')}</select><label class="label" for="formationRowsInput" style="margin-top:8px">Formation (e.g. 1-2-3)</label><input id="formationRowsInput" class="field" placeholder="e.g. 1-2-3" inputmode="numeric" aria-describedby="formationValidation"><div id="formationValidation" class="muted" style="font-size:13px;margin-top:4px">Enter positive row counts totalling one fewer than players per side.</div><input id="formationEditIndex" type="hidden" value=""><button id="saveCustomFormationBtn" class="primary" style="width:100%;margin-top:10px">Save formation</button><button id="clearFormationFormBtn" class="neutral" style="width:100%;margin-top:6px">Clear form</button></div><h3 style="font-size:15px">Saved formations</h3>${items||'<p class="muted">No custom formations saved yet.</p>'}`);const rows=$('formationRowsInput'),count=$('formationPlayerCount'),idx=$('formationEditIndex');function validRows(){const raw=rows.value.trim(),r=raw.split(/[-,\s]+/).map(Number),ok=!!raw&&r.length>0&&r.every(v=>Number.isInteger(v)&&v>0)&&r.reduce((a,b)=>a+b,0)===Number(count.value)-1;rows.style.color=ok||!raw?'':'#dc2626';rows.style.borderColor=ok||!raw?'':'#dc2626';$('formationValidation').textContent=!raw?'Enter positive row counts totalling one fewer than players per side.':ok?'Valid formation. Row total: '+r.reduce((a,b)=>a+b,0)+'.':'Invalid formation — row counts must be positive integers totalling exactly '+(Number(count.value)-1)+'.';$('formationValidation').style.color=ok?'#15803d':!raw?'var(--muted)':'#dc2626';return ok}function reset(){rows.value='';idx.value='';$('saveCustomFormationBtn').textContent='Save formation';validRows()}rows.addEventListener('input',validRows);count.addEventListener('change',validRows);$('clearFormationFormBtn').onclick=reset;document.querySelectorAll('[data-edit-formation]').forEach(b=>b.onclick=()=>{const f=data.settings.formations[Number(b.dataset.editFormation)];if(!f)return;rows.value=f.rows.join('-');count.value=f.players;idx.value=b.dataset.editFormation;$('saveCustomFormationBtn').textContent='Update formation';validRows()});document.querySelectorAll('[data-delete-formation]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.deleteFormation);if(!confirm('Delete this saved formation?'))return;data.settings.formations.splice(i,1);save();manageFormations()});$('saveCustomFormationBtn').onclick=()=>{const players=Number(count.value),r=rows.value.trim().split(/[-,\s]+/).map(Number);if(!validRows())return;const label=r.join('-');const duplicate=(data.settings.formations||[]).findIndex((f,i)=>i!==Number(idx.value)&&Number(f.players)===players&&((f.rows||[]).join('-')===label||String(f.name)===label));if(duplicate>=0)return alert('This formation already exists for that player count.');const obj={name:label,players,rows:r};if(idx.value!=='')data.settings.formations[Number(idx.value)]=obj;else data.settings.formations.push(obj);if(players===Number(m().playersPerSide||7)){m().formation=label;m().formationSlots=null}save();renderFormationChoices();closeModal()}}
function pitchRows(){const n=Number(m().playersPerSide||7),f=String(m().formation||'Custom');const custom=(data.settings.formations||[]).find(x=>x.name===f&&Number(x.players)===n);let rows=custom?(custom.rows||[]):f!=='Custom'?f.split('-').map(Number).filter(x=>x>0):[];if(!rows.length||rows.reduce((a,b)=>a+b,0)!==n-1)rows=formationList(n)[0]?.rows||[2,3,1];return [1,...rows]}
function pitchPlayerIds(){const max=Number(m().playersPerSide||7);let ids;if(Array.isArray(m().formationSlots)&&m().formationSlots.length===max)ids=m().formationSlots.slice();else{ids=(m().startingPlayers||[]).slice(0,max);while(ids.length<max)ids.push(null)}if(!ids.some(Boolean))ids=data.squad.slice(0,max).map(p=>p.id);while(ids.length<max)ids.push(null);return ids.slice(0,max)}
function shirtNumber(p,index){const kits=data.settings.teamKits||[];const kit=kits.find(k=>String(k.colour||'').toLowerCase()===kitColourForPitch())||kits.find(k=>k.name===(m().venueType==='Away'?'Away':'Home'));const kitName=kit?.name;const value=kitName&&p.shirtNumbers?p.shirtNumbers[kitName]:null;return value!==undefined&&String(value).trim()!==''?String(value):String(index+1)}
function renderVisualPitch(){
 const n=Number(m().playersPerSide||7);let selected=null;
 function pitchMarkup(){const ids=pitchPlayerIds(),rows=pitchRows(),ordered=ids.slice();while(ordered.length<n)ordered.push(null);const onPitch=new Set(ordered.filter(Boolean));const subs=data.squad.filter(p=>!onPitch.has(p.id)&&!p.injured&&!(m().unavailablePlayers||[]).includes(p.id));let k=0;const rowHtml=rows.map((count,ri)=>{let slots=[];for(let j=0;j<count;j++){const id=ordered[k],p=data.squad.find(x=>x.id===id),idx=k++;slots.push(`<button type="button" class="pitchslot" data-pitch-player="${id||''}" data-pitch-index="${idx}" aria-label="${p?esc(p.name):'Empty position'}"><span class="pitchshirt" style="background:${esc(m().teamColours||'Blue')}">${p?esc(shirtNumber(p,idx)):''}</span><span class="pitchname">${p?esc(p.name):'Empty space'}</span><span class="pitchpos">${ri===0?'GK':`Row ${ri}`}</span></button>`)}return `<div class="pitchline">${slots.join('')}</div>`}).join('');const subsHtml=subs.map(p=>`<button type="button" class="pitchsub" data-pitch-sub="${p.id}"><span class="pitchshirt" style="background:${esc(m().teamColours||'Blue')}">${esc(shirtNumber(p,data.squad.indexOf(p)))}</span><span class="pitchname" style="color:var(--ink)">${esc(p.name)}</span></button>`).join('')||'<span class="muted">No substitutes available.</span>';return {rowHtml,subsHtml}}
 function paint(){const h=pitchMarkup();$('visualPitchBoard').innerHTML=h.rowHtml;$('visualPitchSubs').innerHTML=h.subsHtml;document.querySelectorAll('[data-pitch-player],[data-pitch-sub]').forEach(el=>{el.onclick=e=>{e.preventDefault();choose(el)}});if(selected){const el=selected.sub?document.querySelector(`[data-pitch-sub="${selected.id}"]`):document.querySelector(`[data-pitch-index="${selected.index}"]`);if(el)el.classList.add('selected')}}
 openModal('Visual formation · '+(m().formation||'Custom'),`<p class="pitchhint">Tap a player, then another to swap positions. Tap a substitute, then a player on the pitch to replace them. Changes remain here until you save.</p><div class="pitchboard" id="visualPitchBoard"></div><h3 style="font-size:15px;margin:14px 0 6px">Substitutes</h3><div class="pitchsubs" id="visualPitchSubs"></div><button type="button" id="saveVisualPitchBtn" class="primary" style="width:100%;margin-top:12px">Save formation & close</button>`);
 function mark(el){document.querySelectorAll('.pitchslot.selected,.pitchsub.selected').forEach(x=>x.classList.remove('selected'));if(el)el.classList.add('selected')}
 function movePlayer(from,to,isSub){const current=pitchPlayerIds();if(to<0||to>=n)return false;if(isSub){const incoming=from,off=current[to];if(!incoming||!off)return false;current[to]=incoming;const active=(m().activePlayers&&m().activePlayers.length?m().activePlayers:m().startingPlayers.slice()).slice();const pos=active.indexOf(off);if(pos>=0)active[pos]=incoming;else if(active.length<n)active.push(incoming);m().activePlayers=active;m().events.push({id:uid(),type:'substitution',playerId:incoming,playerName:playerName(incoming),offPlayerId:off,offPlayerName:playerName(off),at:stamp(),period:m().period||'Not started',text:`Substitution: ${playerName(incoming)} for ${playerName(off)}`});}else{if(from===to||!current[from]||!current[to])return false;[current[from],current[to]]=[current[to],current[from]];}m().formationSlots=current.slice();m().startingPlayers=current.filter(Boolean);if(!m().activePlayers?.length||m().status==='ready')m().activePlayers=m().startingPlayers.slice();m().substitutes=data.squad.map(p=>p.id).filter(id=>!current.includes(id));snapshot();persistData();return true}
 function choose(el){const src=sourceFor(el);if(!src)return;if(!selected){selected=src;mark(el);return}if(selected.sub&&src.sub){selected=src;mark(el);return}if(!selected.sub&&!src.sub&&selected.index===src.index){selected=null;mark(null);return}if(!src.sub&&!src.id)return;if(!selected.sub&&src.sub){if(movePlayer(src.id,Number(selected.index),true)){selected=null;paint()}return}if(selected.sub&&!src.sub){if(movePlayer(selected.id,Number(src.index),true)){selected=null;paint()}return}if(movePlayer(Number(selected.index),Number(src.index),false)){selected=null;paint()}}
 paint();$('saveVisualPitchBtn').onclick=()=>{m().formationSlots=pitchPlayerIds().slice();m().startingPlayers=m().formationSlots.filter(Boolean);m().activePlayers=(m().activePlayers||[]).filter(id=>m().startingPlayers.includes(id));m().substitutes=data.squad.map(p=>p.id).filter(id=>!m().startingPlayers.includes(id));closeModal();save()}
}
function sourceFor(el){if(el.dataset.pitchSub)return {id:el.dataset.pitchSub,sub:true};if(el.dataset.pitchPlayer)return {id:el.dataset.pitchPlayer,index:Number(el.dataset.pitchIndex),sub:false};return null}
function showLineup(){m().unavailablePlayers=[...new Set([...(m().unavailablePlayers||[]),...data.squad.filter(p=>p.injured).map(p=>p.id)])];let selected=new Set((m().startingPlayers.length?m().startingPlayers:data.squad.map(p=>p.id)).filter(id=>!m().unavailablePlayers.includes(id)));openModal('Starting lineup and substitutions',`<label class="label">Starting players <span id="startingCount" class="pill">${selected.size} selected · ${Number(m().playersPerSide||7)} required</span></label><p class="muted">Select exactly the number of players for your team format.</p><div class="stack">${data.squad.map(p=>`<div class="row between" style="padding:5px 0"><label><input type="checkbox" data-starting="${p.id}" ${selected.has(p.id)&&!m().unavailablePlayers.includes(p.id)?'checked':''} ${m().unavailablePlayers.includes(p.id)?'disabled':''}> ${esc(p.name)} ${((m().injuredPlayers||[]).includes(p.id)||p.injured)?'<strong style="color:#dc2626">✚ INJURED</strong>':''} <span class="muted">[${esc((p.position||'Midfield').trim().split(/\s+/).filter(Boolean).map(w=>w.charAt(0).toUpperCase()).join(''))}]</span></label><label class="muted" style="font-size:12px"><input type="checkbox" data-injured="${p.id}" ${p.injured?'checked':''}> Injured</label><label class="muted" style="font-size:12px"><input type="checkbox" data-unavailable="${p.id}" ${m().unavailablePlayers.includes(p.id)?'checked':''}> Unavailable</label></div>`).join('')}</div><button class="primary" id="saveLineupBtn" style="width:100%;margin-top:12px">Save starting lineup</button><hr><p class="muted">To make a substitution during the match, tap the player coming off, then select the player coming on.</p><button class="neutral" id="substituteBtn" style="width:100%">Make substitution</button>`);document.querySelectorAll('[data-injured]').forEach(c=>c.addEventListener('change',()=>{const id=c.dataset.injured,p=data.squad.find(x=>x.id===id);if(!p)return;p.injured=c.checked;m().unavailablePlayers=m().unavailablePlayers||[];if(c.checked){if(!m().unavailablePlayers.includes(id))m().unavailablePlayers.push(id);const start=document.querySelector(`[data-starting="${id}"]`);if(start){start.checked=false;start.disabled=true}}else{m().unavailablePlayers=m().unavailablePlayers.filter(x=>x!==id);const start=document.querySelector(`[data-starting="${id}"]`);if(start)start.disabled=false}const row=c.closest('.row');if(row){const lab=row.querySelector('strong');if(c.checked&&!lab){const nameLabel=row.querySelector('label');nameLabel.insertAdjacentHTML('beforeend',' <strong style="color:#dc2626">✚ INJURED</strong>')}else if(!c.checked&&lab)lab.remove()}save();const n=document.querySelectorAll('[data-starting]:checked').length;$('startingCount').textContent=n+' selected · '+Number(m().playersPerSide||7)+' required'}));document.querySelectorAll('[data-unavailable]').forEach(c=>c.addEventListener('change',()=>{m().unavailablePlayers=m().unavailablePlayers||[];const id=c.dataset.unavailable;if(c.checked){if(!m().unavailablePlayers.includes(id))m().unavailablePlayers.push(id);const start=document.querySelector(`[data-starting="${id}"]`);if(start){start.checked=false;start.disabled=true}}else{m().unavailablePlayers=m().unavailablePlayers.filter(x=>x!==id);const start=document.querySelector(`[data-starting="${id}"]`);if(start)start.disabled=false}const n=document.querySelectorAll('[data-starting]:checked').length;$('startingCount').textContent=n+' selected · '+Number(m().playersPerSide||7)+' required'}));document.querySelectorAll('[data-starting]').forEach(c=>c.addEventListener('change',()=>{const n=document.querySelectorAll('[data-starting]:checked').length;$('startingCount').textContent=n+' selected · '+Number(m().playersPerSide||7)+' required';$('startingCount').style.background=n===Number(m().playersPerSide||7)?'#dcfce7':'#fff8df'}));$('saveLineupBtn').onclick=()=>{let ids=[...document.querySelectorAll('[data-starting]:checked')].map(x=>x.dataset.starting);if(!ids.length)return alert('Choose at least one starting player.');if(ids.length!==Number(m().playersPerSide||7))return alert('You have selected '+ids.length+' players. This match is set to '+Number(m().playersPerSide||7)+'-a-side, so please select exactly '+Number(m().playersPerSide||7)+' starting players.');m().startingPlayers=ids;m().formationSlots=ids.slice();m().activePlayers=ids.slice();m().substitutes=data.squad.map(p=>p.id).filter(id=>!ids.includes(id)&&!(m().unavailablePlayers||[]).includes(id));snapshot();closeModal();save()};$('substituteBtn').onclick=()=>{closeModal();let active=m().activePlayers.length?m().activePlayers:m().startingPlayers;if(!active.length)active=data.squad.map(p=>p.id);openModal('Choose player coming off',active.map(id=>{let p=data.squad.find(x=>x.id===id);return p?`<button class="goalpick" data-sub-off="${id}">${esc(p.name)}</button>`:''}).join(''))}}
function makeSubOff(id){let outs=m().activePlayers.length?m().activePlayers:m().startingPlayers;let choices=data.squad.filter(p=>!outs.includes(p.id)&&!p.injured&&!(m().unavailablePlayers||[]).includes(p.id));openModal('Choose substitute coming on',choices.map(p=>`<button class="goalpick" data-sub-on="${p.id}" data-sub-off-id="${id}">${esc(p.name)} · ${esc(p.position||'Midfield')}</button>`).join('')||'<p>No available substitutes.</p>')}
function makeSubOn(off,on){let a=data.squad.find(p=>p.id===off),b=data.squad.find(p=>p.id===on);if(!a||!b)return;snapshot();if((m().injuredPlayers||[]).includes(on)){m().injuredPlayers=m().injuredPlayers.filter(id=>id!==on);b.injured=false;m().events.push({id:uid(),at:stamp(),period:m().period,type:'injury',playerId:on,playerName:b.name,text:`${b.name} returned fit`})}let active=m().activePlayers.length?m().activePlayers:(m().startingPlayers.length?m().startingPlayers.slice():data.squad.slice(0,Number(m().playersPerSide||7)).map(p=>p.id));active=active.map(id=>id===off?on:id);m().activePlayers=active;m().substitutes=[...new Set([...(m().substitutes||[]),off])].filter(id=>id!==on);const slots=pitchPlayerIds();const slotIndex=slots.indexOf(off);if(slotIndex>=0){slots[slotIndex]=on;m().formationSlots=slots;m().startingPlayers=slots.filter(Boolean)}addEvent({type:'substitution',text:`Substitution: ${a.name} off, ${b.name} on`,playerId:on,playerName:b.name,offPlayerId:off,offPlayerName:a.name});closeModal();save()}
function ensureShootout(){if(!m().shootout)m().shootout={first:'us',turn:'us',our:[],opp:[],finished:false,usedPlayerIds:[]};const so=m().shootout;if(!Array.isArray(so.usedPlayerIds))so.usedPlayerIds=[];return so}
function shootoutScore(){const so=ensureShootout();return {us:so.our.filter(x=>x.outcome==='scored').length,them:so.opp.filter(x=>x.outcome==='scored').length}}
function shootoutScoreFor(match){const so=match&&match.shootout;if(!so||!so.started||!((so.our||[]).length+(so.opp||[]).length))return null;return {us:(so.our||[]).filter(x=>x.outcome==='scored').length,them:(so.opp||[]).filter(x=>x.outcome==='scored').length}}
function shootoutScoreText(match){const sc=shootoutScoreFor(match);return sc?`Pens ${sc.us}–${sc.them}`:''}
function shootoutWinner(){const so=ensureShootout(),a=so.our,b=so.opp,sc=shootoutScore();const usKicks=a.length,themKicks=b.length;/* In the first five, a side wins only when the opponent cannot catch up with their remaining kicks. After five each, sudden death is decided only after both sides have taken the same number of kicks in that phase. */if(usKicks<=5&&themKicks<=5){const usRemaining=5-usKicks,themRemaining=5-themKicks;if(sc.us>sc.them+themRemaining)return 'us';if(sc.them>sc.us+usRemaining)return 'them';return null}if(usKicks>=5&&themKicks>=5&&usKicks===themKicks&&sc.us!==sc.them)return sc.us>sc.them?'us':'them';return null}
function openPenaltyShootout(){try{if(!m().team)m().team='Your team';if(!m().opponent)m().opponent='Opposition';const so=ensureShootout();if(!so.started){openModal('Penalty shootout',`<label class="label" for="shootoutFirstTeam">First penalty</label><select id="shootoutFirstTeam" class="field"><option value="us">${esc(m().team||'Your team')} take first</option><option value="them">${esc(m().opponent||'Opposition')} take first</option></select><p class="muted">Choose which team takes the opening kick.</p><button type="button" class="primary" id="startShootoutNow" style="width:100%;margin-top:10px">Start shootout</button>`);$('startShootoutNow').onclick=()=>{const first=$('shootoutFirstTeam')?.value||'us';beginShootout(first)};return}renderShootoutModal()}catch(err){console.error('Penalty shootout could not open',err);alert('Could not open the penalty shootout. Please close any open dialog and try again.')}}
function beginShootout(first){m().shootout={started:true,first,turn:first,our:[],opp:[],finished:false,usedPlayerIds:[]};m().events.push({id:uid(),type:'shootout',at:stamp(),period:m().period,text:'Penalty shootout started',teamName:'Shootout',outcomeLabel:(first==='us'?(m().team||'Your team'):(m().opponent||'Opposition'))+' take first',ourShootoutScore:0,oppShootoutScore:0});persistData();renderShootoutModal()}
function renderShootoutModal(){const so=ensureShootout(),sc=shootoutScore(),winner=shootoutWinner();if(winner)so.finished=true;const row=(arr,ours)=>arr.map((x,i)=>`<div class="summaryline"><strong>${i+1}. ${esc(x.playerName|| (ours?(m().team||'Your team'):(m().opponent||'Opposition')))}</strong><span style="float:right;font-weight:850;color:${x.outcome==='scored'?'#15803d':'#b91c1c'}">${x.outcome==='scored'?'✓ SCORED':x.outcome==='saved'?'✋ SAVED':'✕ MISSED'}</span></div>`).join('')||'<div class="muted">No penalties yet</div>';let content=`<div class="row" style="align-items:stretch;gap:8px"><div style="flex:1;background:#e8f6ed;border-radius:12px;padding:10px"><div class="muted">${esc(m().team||'Your team')}</div><div style="font-size:32px;font-weight:900">${sc.us}</div>${row(so.our,true)}</div><div style="flex:1;background:#f2f4f7;border-radius:12px;padding:10px"><div class="muted">${esc(m().opponent||'Opposition')}</div><div style="font-size:32px;font-weight:900">${sc.them}</div>${row(so.opp,false)}</div></div>`;
if(winner){content+=`<div class="notice" style="margin-top:10px">${esc(winner==='us'?(m().team||'Your team'):(m().opponent||'Opposition'))} win the shootout!</div><button class="neutral" style="width:100%" data-shootout-reset>New shootout</button>`}
else if(so.turn==='us'){let active=(m().activePlayers.length?m().activePlayers:(m().startingPlayers.length?m().startingPlayers:data.squad.map(p=>p.id))).filter(id=>!(m().redCarded||[]).includes(id));active=active.filter(id=>!so.usedPlayerIds.includes(id));if(!active.length){so.usedPlayerIds=[];active=(m().activePlayers.length?m().activePlayers:(m().startingPlayers.length?m().startingPlayers:data.squad.map(p=>p.id))).filter(id=>!(m().redCarded||[]).includes(id));content+=`<div class="notice">All eligible players have taken a penalty. The list has reset — everyone is available again for sudden death.</div>`}content+=`<p><strong>Your team to take penalty</strong></p><label class="label">Player · ${active.length} available</label><select id="shootoutPlayer" class="field"><option value="">Choose taker…</option>${active.map(id=>`<option value="${id}">${esc(playerName(id))}</option>`).join('')}</select><div class="eventchips" style="margin-top:8px"><button class="green" data-shootout-result="scored" data-shootout-team="us">✓ Scored</button><button class="danger" data-shootout-result="missed" data-shootout-team="us">✕ Missed</button><button class="neutral" data-shootout-result="saved" data-shootout-team="us">✋ Saved</button></div>`}
else {content+=`<p><strong>${esc(m().opponent||'Opposition')} to take penalty</strong></p><div class="eventchips"><button class="green" data-shootout-result="scored" data-shootout-team="them">✓ Scored</button><button class="danger" data-shootout-result="missed" data-shootout-team="them">✕ Missed</button><button class="neutral" data-shootout-result="saved" data-shootout-team="them">✋ Saved</button></div>`}
content+=`<p class="muted">${so.turn==='us'?esc(m().team||'Your team'):esc(m().opponent||'Opposition')} are next. Shootout score is separate from the match score.</p><button type="button" class="neutral" data-shootout-close style="width:100%">Close shootout</button>`;const host=$('modalContent');if(host&&$('modalRoot').querySelector('.modal')){host.innerHTML=content}else{openModal('Penalty shootout',content)}}
function recordShootoutKick(team,outcome){const so=ensureShootout();if(so.finished)return;let player=null;if(team==='us'){const id=$('shootoutPlayer')?.value;if(!id)return alert('Choose the penalty taker.');player=data.squad.find(p=>p.id===id)}const arr=team==='us'?so.our:so.opp;if(team==='us'&&player){if(so.usedPlayerIds.includes(player.id))return alert('That player has already taken a penalty this round. Choose a player who has not taken one yet.');so.usedPlayerIds.push(player.id)}arr.push({playerId:player?.id||null,playerName:player?.name||(m().opponent||'Opposition'),outcome,at:stamp()});const sc=shootoutScore(),label=outcome==='scored'?'Scored':outcome==='saved'?'Saved':'Missed';m().events.push({id:uid(),type:'shootout',text:'Penalty shootout',teamName:team==='us'?(m().team||'Your team'):(m().opponent||'Opposition'),playerName:player?.name||'',outcomeLabel:label,ourShootoutScore:sc.us,oppShootoutScore:sc.them,period:m().period,at:stamp()});so.turn=team==='us'?'them':'us';const win=shootoutWinner();if(win)so.finished=true;persistData();renderShootoutModal()}
function parseClock(s){if(typeof s==='number')return s;const p=String(s||'0:00').split(':').map(Number);return (p[0]||0)*60+(p[1]||0)}
function playerTimeRows(){const total=Math.floor(elapsed()/1000),ids=new Set([...data.squad.map(p=>p.id),...(m().startingPlayers||[]),...(m().activePlayers||[]),...(m().substitutes||[]),...((m().events||[]).filter(e=>e.type==='substitution').flatMap(e=>[e.offPlayerId,e.playerId]).filter(Boolean))]);if(!ids.size)return '<div class="empty">Set a starting lineup to track player time.</div>';const starts={},ends={};(m().startingPlayers||[]).forEach(id=>{starts[id]=0});(m().events||[]).filter(e=>e.type==='substitution').sort((a,b)=>parseClock(a.at)-parseClock(b.at)).forEach(e=>{const t=parseClock(e.at);if(e.offPlayerId)ends[e.offPlayerId]=t;if(e.playerId&&!Object.prototype.hasOwnProperty.call(starts,e.playerId))starts[e.playerId]=t});const active=new Set(m().activePlayers||[]),red=new Set(m().redCarded||[]);return [...ids].map(id=>{const p=data.squad.find(x=>x.id===id)||{id,name:'Unknown player'};let from=starts[id]===undefined?0:starts[id],to=ends[id]!==undefined?ends[id]:(m().status==='finished'?total:(active.has(id)?total:0));let seconds=Math.max(0,Math.min(total,to)-Math.min(total,from));if(m().status==='ready'&&!(m().events||[]).length)seconds=0;return {name:p.name,seconds,percentage:total?Math.round(seconds/total*100):0,active:active.has(id)&&ends[id]===undefined&&!red.has(id)}}).sort((a,b)=>b.seconds-a.seconds||a.name.localeCompare(b.name)).map(p=>`<div class="summaryline row between"><span>${esc(p.name)}${p.active&&m().status!=='finished'?' <span class="pill">Playing</span>':''}</span><strong>${Math.floor(p.seconds/60)}m ${String(p.seconds%60).padStart(2,'0')}s <span class="muted">(${p.percentage}%)</span></strong></div>`).join('')}

function renderTeamKits(){const el=$('teamKitsSettings');if(!el)return;el.innerHTML=(data.settings.teamKits||[]).map((k,i)=>`<div class="kit-row"><div class="kit-fields"><div><label class="label">Kit name</label><input class="field" value="${esc(k.name)}" data-teamkit-name="${i}"></div><div><label class="label">Kit colour</label><input class="field" value="${esc(k.colour)}" data-teamkit-colour="${i}" list="kitColourOptions"></div><button class="danger small" type="button" data-delete-teamkit="${i}">Delete</button></div><div class="muted" style="margin-top:5px">Player shirt numbers for this kit are shown on each player's squad card.</div></div>`).join('')||'<p class="muted">No team kits configured. Add a kit to get started.</p>';let dl=document.getElementById('kitColourOptions');if(!dl){dl=document.createElement('datalist');dl.id='kitColourOptions';document.body.append(dl)}dl.innerHTML=[...new Set([...(data.settings.kitColours||[]),...(data.settings.teamKits||[]).map(k=>k.colour)])].map(c=>`<option value="${esc(c)}"></option>`).join('')}
function renderAgeGroupSettings(){const el=$('ageGroupSettings');if(!el)return;el.innerHTML=(data.settings.ageGroups||[]).map((g,i)=>`<div class="row" style="margin:6px 0"><input class="field" data-age-name="${i}" value="${esc(g.age)}" aria-label="Age group"><select class="field" data-age-players="${i}" aria-label="Players on pitch">${[5,6,7,8,9,10,11].map(n=>`<option value="${n}" ${Number(g.players)===n?'selected':''}>${n}-a-side</option>`).join('')}</select><button class="danger small" data-age-delete="${i}" type="button">×</button></div>`).join('');el.querySelectorAll('[data-age-delete]').forEach(b=>b.onclick=()=>{data.settings.ageGroups.splice(Number(b.dataset.ageDelete),1);renderAgeGroupSettings();renderTeamAgeChoices()})}
function renderTeamAgeChoices(){const el=$('teamAgeGroup');if(!el)return;const current=(data.settings.teams||[]).find(t=>t.name===m().team)?.ageGroup||m().ageGroup||'';el.innerHTML='<option value="">Choose age group…</option>'+(data.settings.ageGroups||[]).map(g=>`<option value="${esc(g.age)}">${esc(g.age)} · ${g.players}-a-side</option>`).join('');el.value=current}
