renderTeamChoices();renderBackupChoices();$('teamName').value=m().team||'';if($('squadTeamName')&&!$('squadTeamName').value)$('squadTeamName').value=m().team||'';if($('teamDirtyNotice'))$('teamDirtyNotice').classList.toggle('hidden',!teamDirty);renderMatchChoices();$('opponent').value=m().opponent||'';$('matchDate').value=m().date||'';$('format').value=m().format||'halves';$('venueType').value=m().venueType||'Home';$('location').value=m().location||'';$('kickoff').value=m().kickoff||'';if($('matchNotes'))$('matchNotes').value=m().notes||'';$('teamColours').value=m().teamColours||'Blue';$('opponentColours').value=m().opponentColours||'Black';$('matchType').value=m().matchType||'League';$('tournamentGroup').value=m().tournamentGroup||'';$('playersPerSide').value=String(m().playersPerSide||7);renderFormationChoices();$('formation').value=m().formation||'2-3-1';$('trackMinutes').checked=m().trackMinutes!==false;
$('clock').textContent=stamp();$('ourScore').textContent=ourGoals();$('oppScore').textContent=oppGoals();$('teamShort').textContent=m().team||'Your team';$('oppShort').textContent=m().opponent||'Opposition';if($('shootoutScoreDisplay'))$('shootoutScoreDisplay').textContent=shootoutScoreText(m())?`(${shootoutScoreText(m())})`:'';if($('bottomClock'))$('bottomClock').textContent=stamp();if($('bottomPeriodClock'))$('bottomPeriodClock').textContent=periodStamp();if($('bottomPeriodLabel'))$('bottomPeriodLabel').textContent=m().period==='Not started'?'Not started':m().period==='Full time'?'Full time':m().period;if($('bottomScore'))$('bottomScore').textContent=ourGoals()+' – '+oppGoals();if($('bottomShootoutScore')){const penText=shootoutScoreText(m());$('bottomShootoutScore').textContent=penText;$('bottomShootoutScore').classList.toggle('hidden',!penText)}if($('bottomTeam'))$('bottomTeam').textContent=m().team||'Your team';if($('bottomOpp'))$('bottomOpp').textContent=m().opponent||'Opposition';if($('periodClock'))$('periodClock').textContent=periodStamp();
