function scoreBefore(id){let a=0,b=0;for(const e of m().events){if(e.id===id)break;if(e.type==='goal')a++;if(e.type==='opponentGoal')b++}return{ours:a,opp:b}}
function renderSummaries(){let ends=m().events.filter(e=>e.type==='periodEnd');$('summary').innerHTML=ends.length?ends.slice().reverse().map(e=>`<div class="summaryline"><div class="row between"><strong>${esc(e.text)}</strong><strong>${e.totalOurs??ourGoals()}–${e.totalOpp??oppGoals()}</strong></div><div class="muted">${esc(e.at)} · Cumulative score</div>${m().events.filter(g=>g.period===e.period&&(g.type==='goal'||g.type==='opponentGoal')).map(g=>`<div class="muted">${esc(g.at)} · ${g.type==='goal'?esc(g.scorerName)+(g.assistName?' (A: '+esc(g.assistName)+')':''):'Opposition goal'}</div>`).join('')||'<div class="muted">No goals in this period.</div>'}</div>`).join(''):'<p class="muted">A summary is created each time you end a half or quarter.</p>'}
const BASE_STAT_TYPES=[['goal','Goals'],['assist','Assists'],['corner','Corners'],['freeKick','Free kicks'],['penalty','Penalties'],['shot','Shots'],['save','Saves'],['fouled','Fouls won'],['throwIn','Throw-ins'],['yellowCard','Yellow cards'],['redCard','Red cards'],['injury','Injuries'],['opponentGoal','Opposition goals'],['playerOfTheMatch','Player of the match']];
function statTypes(){const extra=(data.settings.extraEvents||[]).map(x=>[x.key,x.label||x.key]);return [...BASE_STAT_TYPES,...extra.filter(x=>!BASE_STAT_TYPES.some(b=>b[0]===x[0]))]}
function selectedStatTypes(){const boxes=[...document.querySelectorAll('[data-stat-type]')];return boxes.length?boxes.filter(b=>b.checked).map(b=>b.dataset.statType):['goal','assist']}
function renderStatFilters(){const root=$('statEventFilters');if(!root)return;const previous=new Set(selectedStatTypes());root.innerHTML=statTypes().map(([key,label])=>`<label class="eventchip" style="display:inline-flex;align-items:center;gap:5px;padding:5px 8px"><input type="checkbox" data-stat-type="${esc(key)}" ${previous.has(key)||(!root.dataset.ready&&['goal','assist'].includes(key))?'checked':''} style="width:auto">${esc(label)}</label>`).join('');root.dataset.ready='1';root.querySelectorAll('[data-stat-type]').forEach(cb=>cb.onchange=()=>{renderStats();renderSeasonStats()})}
function eventStatCount(match, playerId, type){const ev=match.events||[];const playerObj=(match.squadSnapshot||[]).find(p=>p.id===playerId)||data.squad.find(p=>p.id===playerId);const playerLabel=String(playerObj?.name||'').trim().toLowerCase();const samePlayer=(e,idField,nameFields)=>e[idField]===playerId||(playerLabel&&nameFields.some(n=>String(e[n]||'').trim().toLowerCase()===playerLabel));if(type==='goal')return ev.filter(e=>e.type==='goal'&&samePlayer(e,'playerId',['playerName','scorerName'])).length;if(type==='assist')return ev.filter(e=>e.type==='goal'&&samePlayer(e,'assistId',['assistName'])).length;if(type==='penalty'){const inMatch=ev.filter(e=>(e.type==='penalty_goal'||(e.type==='goal'&&e.sourceType==='penalty'))&&e.playerId===playerId).length;const so=match.shootout||{};const shootout=(so.our||[]).filter(k=>k.playerId===playerId&&k.outcome==='scored').length;return {main:inMatch,shootout}}
if(type==='playerOfTheMatch')return match.playerOfTheMatch&&(match.playerOfTheMatch.playerId===playerId||(playerLabel&&String(match.playerOfTheMatch.playerName||'').trim().toLowerCase()===playerLabel))?1:0;if(type==='injury')return ev.filter(e=>(e.type==='injury'||e.type==='injured')&&e.playerId===playerId&&/injured/i.test(e.text||'')).length;
if(type==='shot')return ev.filter(e=>((e.type==='shot'||String(e.type||'').startsWith('shot_'))||(e.type==='goal'&&e.sourceType==='shot'))&&samePlayer(e,'playerId',['playerName','scorerName'])).length;return ev.filter(e=>e.type===type&&samePlayer(e,'playerId',['playerName','scorerName'])).length}
function statDisplay(value,type){if(type==='penalty')return `${value.main} (${value.shootout} shootout${value.shootout===1?'':'s'})`;return String(value)}
function statTotalForMatch(match,type){if(type==='goal')return (match.events||[]).filter(e=>e.type==='goal').length;if(type==='assist')return (match.events||[]).filter(e=>e.type==='goal'&&e.assistId).length;if(type==='penalty'){const main=(match.events||[]).filter(e=>e.type==='penalty_goal'||(e.type==='goal'&&e.sourceType==='penalty')).length;return {main,shootout:((match.shootout||{}).our||[]).filter(k=>k.outcome==='scored').length}}
if(type==='playerOfTheMatch')return match.playerOfTheMatch?1:0;if(type==='injury')return (match.events||[]).filter(e=>(e.type==='injury'||e.type==='injured')&&/injured/i.test(e.text||'')).length;
if(type==='shot')return (match.events||[]).filter(e=>(e.type==='shot'||String(e.type||'').startsWith('shot_'))||(e.type==='goal'&&e.sourceType==='shot')).length;return (match.events||[]).filter(e=>e.type===type).length}
