function trainingAttendeesFromUI(){return [...document.querySelectorAll('[data-training-player]:checked')].map(x=>({team:x.dataset.playerTeam,playerId:x.dataset.playerId,name:x.dataset.playerName}))}
function renderTrainingStarChoices(){const el=$('trainingStar');if(!el)return;const attendees=trainingAttendeesFromUI(),old=el.value;el.innerHTML='<option value="">None</option>'+attendees.map((p,i)=>`<option value="${esc(p.team+'||'+p.playerId)}">${esc(p.name)} · ${esc(p.team)}</option>`).join('');if([...el.options].some(o=>o.value===old))el.value=old}
function renderTraining(){if(!$('trainingView'))return;if(!Array.isArray(data.trainingSessions))data.trainingSessions=[];const teamHost=$('trainingTeams');if(teamHost){const selected=new Set(trainingSelectedTeams());teamHost.innerHTML=trainingTeams().map(t=>`<label class="eventchip" style="display:inline-flex;align-items:center;gap:6px;margin:3px"><input type="checkbox" data-training-team value="${esc(t.name)}" ${selected.has(t.name)?'checked':''}>${esc(t.name)}</label>`).join('')||'<p class="muted">Create and save teams on the Team page before recording training attendance.</p>';teamHost.querySelectorAll('[data-training-team]').forEach(cb=>cb.onchange=renderTrainingRoster)}renderTrainingRoster();const list=$('trainingSessionList');if(list){const sessions=[...data.trainingSessions].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));list.innerHTML=sessions.length?sessions.map(s=>`<div class="summaryline"><div class="row between"><strong>${esc(s.date||'Undated training')}</strong><span class="inlinepill">Training</span></div><div>${esc(s.location||'Location not set')}</div><div class="muted">Teams: ${esc((s.teams||[]).join(', ')||'None')} · ${(s.attendees||[]).length} attended</div><div class="muted">Star of training: ${esc(s.star?.name||'None')}${s.star?.team?' · '+esc(s.star.team):''}</div>${s.notes?`<p style="white-space:pre-wrap">${esc(s.notes)}</p>`:''}<div class="row"><button class="neutral small" data-edit-training="${esc(s.id)}">Edit</button><button class="danger small" data-delete-training="${esc(s.id)}">Delete</button></div></div>`).join(''):'<div class="empty">No training sessions saved yet.</div>'}}
function resetTrainingForm(){if($('trainingDate'))$('trainingDate').value=safeDate();if($('trainingLocation'))$('trainingLocation').value='';if($('trainingNotes'))$('trainingNotes').value='';if($('trainingEditId'))$('trainingEditId').value='';document.querySelectorAll('[data-training-team],[data-training-player]').forEach(x=>x.checked=false);renderTraining()}
