function renderResultForm(){const teams=$('resultTeam');if(!teams)return;const saved=(data.settings.teams||[]).map(t=>t.name);const names=[...new Set([...saved,...(m().team?[m().team]:[])])];const old=teams.value;teams.innerHTML='<option value="">Choose team…</option>'+names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');teams.value=names.includes(old)?old:(names.includes(m().team)?m().team:'');const team=teams.value;const savedTeam=(data.settings.teams||[]).find(t=>t.name===team);const kits=savedTeam?.kits||savedTeam?.teamKits||data.settings.teamKits||[];$('resultYourKit').innerHTML=kits.map(k=>`<option value="${esc(k.colour||k.name)}">${esc(k.name)} — ${esc(k.colour||'')}</option>`).join('')||'<option>Blue</option>';const players=resultPlayers();const potm=$('resultPOTM'),prior=potm.value;potm.innerHTML='<option value="">None</option>'+players.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');if(players.some(p=>p.id===prior))potm.value=prior;resultLineupIds=resultLineupIds.filter(id=>players.some(p=>p.id===id));const summary=$('resultLineupSummary');if(summary)summary.textContent=resultLineupIds.length?resultLineupIds.map(id=>players.find(p=>p.id===id)?.name).filter(Boolean).join(', '):'No lineup selected';if(!$('resultDate').value)$('resultDate').value=safeDate();renderResultEventLog()}
function resultRecordEvent(type,player){const p=player||null;let ev;if(type==='goal'){ev={id:uid(),type:'goal',playerId:p?.id||null,scorerName:p?.name||'Unknown scorer',at:'FT',period:'Result',text:'Goal: '+(p?.name||'Unknown scorer')}}else if(type==='assist'){const goal=[...resultDraftEvents].reverse().find(e=>e.type==='goal');if(goal){goal.assistId=p?.id||null;goal.assistName=p?.name||'';goal.text+=' (Assist: '+(p?.name||'Unknown')+')';ev={id:uid(),type:'assist',playerId:p?.id||null,goalId:goal.id,at:'FT',period:'Result',text:'Assist: '+(p?.name||'Unknown scorer')}}else{ev={id:uid(),type:'assist',playerId:p?.id||null,at:'FT',period:'Result',text:'Assist: '+(p?.name||'Unknown')}}}else if(type==='opponentGoal')ev={id:uid(),type:'opponentGoal',at:'FT',period:'Result',text:'Opposition goal'};else ev={id:uid(),type,playerId:p?.id||null,at:'FT',period:'Result',text:eventLabel(type)+(p?' · '+p.name:'')};resultDraftEvents.push(ev);if(type==='goal')$('resultScored').value=String(Math.max(0,Number($('resultScored').value)||0)+1);if(type==='opponentGoal')$('resultConceded').value=String(Math.max(0,Number($('resultConceded').value)||0)+1);renderResultEventLog()}
function resultChoosePlayer(type){const players=resultPlayers();if(type==='opponentGoal'){resultRecordEvent(type);return}const choices=players.map(p=>`<button class="goalpick" type="button" data-result-player-event="${esc(type)}" data-result-player-id="${esc(p.id)}"><strong>${esc(p.name)}</strong></button>`).join('');const extra=type==='goal'?'<button class="goalpick" type="button" data-result-unknown-goal="1"><strong>Unknown scorer</strong><span class="muted">Goal scored, player not known</span></button>':'';openModal('Record '+eventLabel(type),(extra+choices)||'<p>No players available. Choose your team first.</p>')}
function showResultLineup(){const players=resultPlayers();if(!players.length)return alert('Choose your team first.');const selected=new Set(resultLineupIds.length?resultLineupIds:players.map(p=>p.id));openModal('Starting lineup / subs',`<p class="muted">Select the players who took part in this previous match. This uses the selected team's saved squad.</p><div class="stack">${players.map(p=>`<label class="row"><input type="checkbox" data-result-lineup-choice="${esc(p.id)}" ${selected.has(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div><button type="button" class="primary" id="saveResultLineup" style="width:100%;margin-top:12px">Save lineup</button>`);$('saveResultLineup').onclick=()=>{resultLineupIds=[...document.querySelectorAll('[data-result-lineup-choice]:checked')].map(x=>x.dataset.resultLineupChoice);closeModal();renderResultForm()}}
function savePreviousResult(){const team=$('resultTeam')?.value||'',opponent=$('resultOpponent')?.value.trim()||'';if(!team)return alert('Choose your team first.');if(!opponent)return alert('Enter the opposition.');const players=resultPlayers(),scored=Math.max(0,Number($('resultScored').value)||0),conceded=Math.max(0,Number($('resultConceded').value)||0),events=resultDraftEvents.map(e=>({...e}));const goalCount=events.filter(e=>e.type==='goal').length;for(let i=goalCount;i<scored;i++)events.push({id:uid(),type:'goal',playerId:null,scorerName:'Unknown scorer',at:'FT',period:'Result',text:'Goal: Unknown scorer'});while(events.filter(e=>e.type==='goal').length>scored){const i=events.map(e=>e.type).lastIndexOf('goal');events.splice(i,1)}const oppCount=events.filter(e=>e.type==='opponentGoal').length;for(let i=oppCount;i<conceded;i++)events.push({id:uid(),type:'opponentGoal',at:'FT',period:'Result',text:'Opposition goal'});while(events.filter(e=>e.type==='opponentGoal').length>conceded){const i=events.map(e=>e.type).lastIndexOf('opponentGoal');events.splice(i,1)}const potmId=$('resultPOTM').value,potm=players.find(p=>p.id===potmId);if(potm)events.push({id:uid(),type:'playerOfTheMatch',playerId:potm.id,playerName:potm.name,at:'FT',period:'Full time',text:'🏆 Player of the Match: '+potm.name});const match={...freshMatch(team),team,opponent,date:$('resultDate').value||safeDate(),location:$('resultLocation').value.trim(),venueType:$('resultVenue').value,teamColours:$('resultYourKit').value,opponentColours:$('resultOppKit').value,matchType:'Previous result',notes:$('resultNotes').value||'',status:'finished',period:'Full time',elapsedMs:0,runningSince:null,events,startingPlayers:resultLineupIds.slice(),activePlayers:[],substitutes:players.map(p=>p.id).filter(id=>!resultLineupIds.includes(id)),resultEntry:true,penalties:null,playerOfTheMatch:potm?{playerId:potm.id,playerName:potm.name}:null,createdAt:new Date().toISOString()};const pf=$('resultPensFor').value,pa=$('resultPensAgainst').value;if(pf!==''||pa!=='')match.penalties={our:Math.max(0,Number(pf)||0),opp:Math.max(0,Number(pa)||0)};const kicks=events.filter(e=>e.type==='shootout');if(kicks.length){match.shootout={started:true,first:kicks[0].team||'us',turn:'us',finished:true,usedPlayerIds:[],our:kicks.filter(e=>e.team==='us').map(e=>({playerId:e.playerId||null,playerName:e.playerName||'',outcome:e.outcome,at:'FT'})),opp:kicks.filter(e=>e.team==='them').map(e=>({playerId:null,playerName:e.teamName||opponent,outcome:e.outcome,at:'FT'}))}}data.matches.push(match);persistData();renderHistory();renderStats();alert('Previous result saved to match reports and player statistics.');['resultOpponent','resultLocation','resultScored','resultConceded','resultPensFor','resultPensAgainst','resultNotes'].forEach(id=>{if($(id))$(id).value=''});resultDraftEvents=[];resultLineupIds=[];$('resultPOTM').value='';$('resultScored').value='0';$('resultConceded').value='0';renderResultForm()}

function renderTrainingStats(){const host=$('trainingStats');if(!host)return;const mode=$('trainingStatsFilter')?.value||'all',sessions=(data.trainingSessions||[]).filter(s=>mode==='all'||s.teams?.includes(mode));const tally={};sessions.forEach(s=>(s.attendees||[]).forEach(p=>{const k=p.team+'||'+p.name;tally[k]=tally[k]||{team:p.team,name:p.name,attended:0,stars:0};tally[k].attended++}));sessions.forEach(s=>{if(s.star){const k=s.star.team+'||'+s.star.name;tally[k]=tally[k]||{team:s.star.team,name:s.star.name,attended:0,stars:0};tally[k].stars++}});const teams=[...new Set(trainingTeams().map(t=>t.name))];const filter=$('trainingStatsFilter');if(filter){const old=filter.value;filter.innerHTML='<option value="all">All teams</option>'+teams.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');filter.value=teams.includes(old)?old:'all'}const rows=Object.values(tally).filter(x=>mode==='all'||x.team===mode).sort((a,b)=>a.team.localeCompare(b.team)||a.name.localeCompare(b.name));host.innerHTML=`<p class="muted">${sessions.length} training sessions · attendance and Star of Training totals.</p>`+(rows.length?`<div style="overflow-x:auto"><table class="stat-table"><thead><tr><th>Team</th><th>Player</th><th>Sessions attended</th><th>Stars</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.team)}</td><td>${esc(p.name)}</td><td>${p.attended}</td><td>${p.stars}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No training statistics for this filter yet.</p>')}
function renderCombinedTimeline(){const host=$('combinedTimeline');if(!host)return;const selectedTeam=$('statsTeamSelect')?.value||'all',mode=$('recordTypeFilter')?.value||'all';const matches=(data.matches||[]).map((record,index)=>{const n=normaliseSavedMatch(record,index);return {kind:'match',date:n.match.date||'',record,index,match:n.match}}).filter(x=>selectedTeam==='all'||x.match.team===selectedTeam).filter(x=>selectedPeriodMatches([{match:x.match}]).length>0);const sessions=(data.trainingSessions||[]).map(s=>({kind:'training',date:s.date||'',session:s})).filter(x=>selectedTeam==='all'||(x.session.teams||[]).includes(selectedTeam));const items=[...(mode==='training'?[]:matches),...(mode==='matches'?[]:sessions)].sort((a,b)=>String(b.date).localeCompare(String(a.date))||((a.kind==='training'?b.session?.createdAt:b.match?.date)||'').localeCompare((b.kind==='training'?a.session?.createdAt:a.match?.date)||''));host.innerHTML=items.length?items.map(x=>x.kind==='match'?`<div class="summaryline"><div class="row between"><strong>${esc(x.date)} · ${esc(x.match.team||'Team')} vs ${esc(x.match.opponent||'Opposition')}</strong><span class="inlinepill">Match</span></div><div>${x.match.events.filter(e=>e.type==='goal').length}–${x.match.events.filter(e=>e.type==='opponentGoal').length}${shootoutScoreText(x.match)?' · '+esc(shootoutScoreText(x.match)):''}</div><button class="neutral small" data-loadhistory="${x.index}">View match report</button></div>`:`<div class="summaryline"><div class="row between"><strong>${esc(x.date)} · Training</strong><span class="inlinepill">Training</span></div><div>${esc(x.session.location||'Location not set')} · ${esc((x.session.teams||[]).join(', '))}</div><div class="muted">${(x.session.attendees||[]).length} attended${x.session.star?' · Star: '+esc(x.session.star.name):''}</div>${x.session.notes?`<p style="white-space:pre-wrap">${esc(x.session.notes)}</p>`:''}</div>`).join(''):'<div class="empty">No matches or training sessions match these filters.</div>'}
function renderHistory(){
 renderCombinedTimeline();renderTrainingStats();
 const selectedTeam=$('statsTeamSelect')?.value||'all';
 const normalised=(Array.isArray(data.matches)?data.matches:[]).map((record,index)=>normaliseSavedMatch(record,index));
 const filteredItems=normalised.filter(({match})=>selectedTeam==='all'||match.team===selectedTeam).filter(({match})=>selectedPeriodMatches([{match}]).length>0);
 const historyFallback=false;
 const items=filteredItems.slice().reverse();
 const host=$('historyList');if(!host)return;
 const current=m();

 const summary=`<p class="muted" style="margin:0 0 10px">Showing ${items.length} of ${normalised.length} saved matches · ${esc(selectedTeam==='all'?'All teams':selectedTeam)} · season and competition filters applied.</p>`;

 if(!items.length){host.innerHTML=summary+`<div class="empty">${normalised.length?'No saved matches match the selected filters. Try Clear filters.':'No saved matches are stored in this browser yet. If you expected existing matches, check the version diagnostics and use Import backup to restore a Touchline Tracker backup.'}</div>`;return}
 const byTeam=new Map();
 items.forEach(it=>{const mm=it.match,team=mm.team||'Unnamed team',season=String(mm.season||seasonForDate(mm.date||'')||'Unassigned season'),group=mm.tournamentGroup?`Tournament · ${mm.tournamentGroup}`:(mm.matchType||'League');if(!byTeam.has(team))byTeam.set(team,new Map());const bySeason=byTeam.get(team);if(!bySeason.has(season))bySeason.set(season,new Map());const byGroup=bySeason.get(season);if(!byGroup.has(group))byGroup.set(group,[]);byGroup.get(group).push(it)});
 const body=[...byTeam.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([team,seasons])=>`<details open class="summaryline"><summary style="cursor:pointer;font-weight:850;font-size:1.05rem">${esc(team)} <span class="muted">· ${[...seasons.values()].reduce((n,g)=>n+[...g.values()].reduce((k,a)=>k+a.length,0),0)} matches</span></summary>${[...seasons.entries()].sort((a,b)=>b[0].localeCompare(a[0])).map(([season,groups])=>`<details open class="summaryline"><summary style="cursor:pointer;font-weight:750">${esc(season)}</summary>${[...groups.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([heading,arr])=>`<div class="summaryline"><strong>${esc(heading)}</strong>${arr.map(({record,index,match})=>{const goals=record.goals??match.events.filter(e=>e.type==='goal').length,opGoals=record.opponentGoals??match.events.filter(e=>e.type==='opponentGoal').length;return `<div class="summaryline"><strong>${esc(match.date||'Undated')} · ${esc(match.team)} vs ${esc(match.opponent)}</strong><div class="muted">${esc(match.matchType)}${match.tournamentGroup?' · '+esc(match.tournamentGroup):''} · ${esc(match.venueType||'Home')} · ${goals}–${opGoals} · ${esc(match.format==='halves'?'2 halves':'4 quarters')}</div>${shootoutScoreText(match)?`<div class="muted">Penalty shootout: ${esc(shootoutScoreText(match))}</div>`:''}<div class="row"><button class="neutral small" data-loadhistory="${index}">View report</button><button class="danger small" data-deletematch="${index}">Delete match</button></div></div>`}).join('')}</div>`).join('')}</details>`).join('')}</details>`).join('');
 host.innerHTML=summary+body;bindSave();
}
function calculatePlayerMinutes(match){const ev=match.events||[],endMs=match.elapsedMs||0,starts=(match.startingPlayers&&match.startingPlayers.length?match.startingPlayers:(match.activePlayers||[])).slice();let on=new Set(starts),last=0,totals={};const parse=t=>{const a=String(t||'0:00').split(':').map(Number);return ((a[0]||0)*60+(a[1]||0))*1000};const add=(id,ms)=>{if(id)totals[id]=(totals[id]||0)+Math.max(0,ms)};for(const e of ev.slice().sort((a,b)=>parse(a.at)-parse(b.at))){const now=parse(e.at);on.forEach(id=>add(id,now-last));last=now;if(e.type==='substitution'){on.delete(e.offPlayerId);on.add(e.playerId)}if(e.type==='redCard')on.delete(e.playerId)}on.forEach(id=>add(id,endMs-last));return Object.entries(totals).map(([id,ms])=>({name:(match.squadSnapshot||[]).find(p=>p.id===id)?.name||data.squad.find(p=>p.id===id)?.name||'Player',ms}))}
function report(match=m()){let outer=null;if(match&&match.match){outer=match;match=outer.match;if(!match.shootout&&outer.shootout)match={...match,shootout:outer.shootout};}let ev=match.events||[],g=ev.filter(e=>e.type==='goal'),o=ev.filter(e=>e.type==='opponentGoal'),so=match.shootout||outer?.shootout||null;const kicks=[...(so?.our||[]).map((x,i)=>({...x,side:match.team||'Your team',order:i+1})),...(so?.opp||[]).map((x,i)=>({...x,side:match.opponent||'Opposition',order:i+1}))];return [`${match.team||'Your team'} (${match.teamColours||'Blue'}) vs ${match.opponent||'Opposition'} (${match.opponentColours||'Black'})`,`${match.date||''} · ${match.matchType||'League'}${match.tournamentGroup?' · '+match.tournamentGroup:''} · ${match.venueType||'Home'} · ${match.format==='halves'?'2 halves':'4 quarters'}${match.location?' · '+match.location:''}${match.kickoff?' · KO '+match.kickoff:''}`,`Score: ${g.length}–${o.length}`,...(match.playerOfTheMatch?[`Player of the Match: ${match.playerOfTheMatch.playerName||'Unknown player'}`]:[]),...(String(match.notes||'').trim()?['','NOTES',String(match.notes).trim()]:[]),...(shootoutScoreText(match)?[`Penalty shootout: ${shootoutScoreText(match).replace('Pens ','')}`,'PENALTY TAKERS',...kicks.sort((a,b)=>a.order-b.order||(a.side===match.team?-1:1)).map(x=>`${x.side} · ${x.order}. ${x.playerName||'Unknown taker'} — ${x.outcome==='scored'?'SCORED':x.outcome==='saved'?'SAVED':'MISSED'}${x.at?' · '+x.at:''}`)]:[]),'','FULL MATCH TIMELINE',...ev.map(e=>`${e.at||'--:--'} [${e.period||''}] ${e.type==='goal'?`GOAL: ${e.scorerName||playerName(e.playerId)}${e.assistName?' (Assist: '+e.assistName+')':''}`:e.type==='opponentGoal'?'🔴 Opposition goal':e.type==='shootout'&&e.outcomeLabel?`PENALTY: ${e.teamName||''} — ${e.playerName?e.playerName+' — ':''}${e.outcomeLabel}`:e.text||eventLabel(e.type)||e.type}`),'','PLAYER GAME TIME',...(match.trackMinutes===false?['Tracking disabled for this match']:calculatePlayerMinutes(match).map(x=>`${x.name}: ${fmt(x.ms)} (${match.elapsedMs?Math.round(x.ms/match.elapsedMs*100):0}%)`))].join('\n')}
function exportBackup(){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='touchline-tracker-backup-'+(new Date().toISOString().slice(0,10))+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function startNew(){const shouldArchive=matchHasContent();if(shouldArchive&&!confirm('Start a new match? The current match will be saved to history first.'))return;if(shouldArchive&&!m().historySaved){if(m().status==='running')m().elapsedMs=elapsed();m().runningSince=null;if(m().status==='running')m().status='paused';archiveFinishedMatch();persistData()}let team=m().team;data.match=freshMatch(team);save();setTab('live')}
function setTab(tab){if(['live','training','result'].includes(tab))currentGamePage=tab;document.querySelectorAll('button.tab[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const selected=currentGamePage||'live';if($('livePageSelect'))$('livePageSelect').value=['live','training','result'].includes(tab)?tab:'';['live','training','result','squad','history','settings'].forEach(t=>{const el=$(t+'View');if(el)el.classList.toggle('hidden',t!==(tab==='game'?selected:tab))});if(tab==='training'||(tab==='game'&&selected==='training')){renderTraining();renderTrainingStats()}if(tab==='game'&&selected==='result')renderResultForm();render()}
function setLiveSubpage(page){if(!['live','training','result'].includes(page))return;currentGamePage=page;const selector=$('livePageSelect');if(selector)selector.value=page;document.querySelectorAll('button.tab[data-tab]').forEach(b=>b.classList.remove('active'));['live','training','result','squad','history','settings'].forEach(t=>{const el=$(t+'View');if(el)el.classList.toggle('hidden',t!==page)});if(page==='training'){renderTraining();renderTrainingStats()}if(page==='result')renderResultForm();render()}
function downloadJSON(obj,filename){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backupSelectedParts(){const parts=[...document.querySelectorAll('[data-backup-part]:checked')].map(x=>x.dataset.backupPart);return parts.includes('allData')?['allData']:parts}
function selectedMatchRows(team,filter){return data.matches.filter(r=>{const x=r.match||r;if(team!=='all'&&x.team!==team)return false;if(filter==='allSeasons')return !!(x.season||data.settings.seasons?.some(s=>x.date>=s.start&&x.date<=s.end));if(filter==='specificSeason'){const n=$('backupSeasonSelect').value;const season=data.settings.seasons?.find(s=>s.name===n);return n&&(x.season===n||(season&&x.date>=season.start&&x.date<=season.end))}if(filter==='tournament')return !!$('backupTournamentSelect').value&&x.tournamentGroup===$('backupTournamentSelect').value;return false})}
function exportTeamData(){const team=$('teamBackupSelect').value,parts=backupSelectedParts();if(!parts.length)return alert('Choose at least one data type to export.');const payload={format:'touchline-tracker-selective-backup',version:1,team,createdAt:new Date().toISOString(),sections:{}};const includeAll=parts.includes('allData');if(includeAll||parts.includes('squads'))payload.sections.squads=(data.settings.teams||[]).filter(t=>team==='all'||t.name===team).map(t=>({...t,players:JSON.parse(JSON.stringify(t.players||[])),kits:JSON.parse(JSON.stringify(t.kits||t.teamKits||[]))}));if(includeAll)payload.sections.allMatches=data.matches.filter(r=>team==='all'||(r.match||r).team===team);if(includeAll||parts.includes('allSeasons'))payload.sections.allSeasons=selectedMatchRows(team,'allSeasons');if(includeAll||parts.includes('specificSeason')){if(!$('backupSeasonSelect').value&&!includeAll)return alert('Choose a season first.');payload.sections.specificSeason=selectedMatchRows(team,'specificSeason')}if(includeAll||parts.includes('tournament')){if(!$('backupTournamentSelect').value&&!includeAll)return alert('Choose a tournament first.');payload.sections.tournament=selectedMatchRows(team,'tournament')}if(includeAll||parts.includes('currentMatch'))payload.sections.currentMatch=(team==='all'||m().team===team)?m():null;if(includeAll||parts.includes('trainingSessions'))payload.sections.trainingSessions=(data.trainingSessions||[]).filter(s=>team==='all'||(s.teams||[]).includes(team));if(includeAll||parts.includes('settings'))payload.sections.settings={seasons:data.settings.seasons,competitionTypes:data.settings.competitionTypes,clubs:data.settings.clubs,kitColours:data.settings.kitColours,teamKits:data.settings.teamKits};downloadJSON(payload,'touchline-team-data-'+(team==='all'?'all-teams':team.trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'team')+'-'+new Date().toISOString().slice(0,10)+'.json')}
let pendingSelectiveImport=null;
async function importTeamDataFile(file){if(!file)return;try{const parsed=JSON.parse(await file.text());let x=parsed;if(x&&typeof x==='object'&&!x.sections&&Array.isArray(x.squad)&&x.match&&Array.isArray(x.matches)){x={format:'touchline-tracker-selective-backup',sections:{squads:[{name:x.match.team||'Imported team',players:x.squad,kits:x.settings?.teamKits||[]}],allMatches:x.matches,currentMatch:x.match,settings:x.settings||{}}}}if(!x||typeof x!=='object'||!x.sections)throw Error('invalid');pendingSelectiveImport=x;const available=Object.keys(x.sections).filter(k=>x.sections[k]!==null&&x.sections[k]!==undefined);openModal('Choose data to import',`<p class="muted">Select the sections you want to import from this backup.</p><div class="stack">${available.map((k,i)=>`<label><input type="checkbox" data-import-section="${esc(k)}" checked> ${esc(({squads:'Squads and player lists',allMatches:'All match history',allSeasons:'Season match data',specificSeason:'Specific season',tournament:'Tournament match data',currentMatch:'Current match',settings:'Team settings',trainingSessions:'Training sessions'}[k]||k))}</label>`).join('')}</div><button class="primary" id="confirmSelectiveImport" style="width:100%;margin-top:12px">Import selected data</button>`)}catch(err){alert('Could not read this selective Touchline Tracker backup.')}}
function applySelectiveImport(){if(!pendingSelectiveImport)return;const x=pendingSelectiveImport,selected=[...document.querySelectorAll('[data-import-section]:checked')].map(el=>el.dataset.importSection);if(!selected.length)return alert('Select at least one section to import.');if(!confirm('Import selected sections? Matching squads/settings may be updated and new match records added.'))return;for(const k of selected){const v=x.sections[k];if(k==='squads'){data.settings.teams=data.settings.teams||[];for(const t of (Array.isArray(v)?v:[])){const j=data.settings.teams.findIndex(a=>a.name===t.name);if(j>=0)data.settings.teams[j]={...data.settings.teams[j],...t,kits:t.kits||t.teamKits||data.settings.teams[j].kits||[]};else data.settings.teams.push({...t,kits:t.kits||t.teamKits||[]})}}else if(k==='allMatches'||k==='allSeasons'||k==='specificSeason'||k==='tournament'){data.matches=data.matches||[];for(const r of (Array.isArray(v)?v:[])){const rm=r.match||r;const exists=data.matches.some(a=>{const am=a.match||a;return am.date===rm.date&&am.team===rm.team&&am.opponent===rm.opponent&&JSON.stringify(am.events||[])===JSON.stringify(rm.events||[])});if(!exists)data.matches.push(r)}}else if(k==='trainingSessions'){data.trainingSessions=Array.isArray(data.trainingSessions)?data.trainingSessions:[];for(const s of (Array.isArray(v)?v:[])){const i=data.trainingSessions.findIndex(a=>a.id&&a.id===s.id);if(i>=0)data.trainingSessions[i]={...data.trainingSessions[i],...s};else data.trainingSessions.push(s)}}else if(k==='currentMatch'){if(v&&confirm('Replace the current match with the imported match?'))data.match=v}else if(k==='settings'){Object.assign(data.settings,v)}}pendingSelectiveImport=null;save();closeModal();alert('Selected backup data imported.')}

function bindSimpleListBackup(exportId,importId,fileId,key,label){$(exportId).onclick=()=>downloadJSON({format:'touchline-tracker-'+key,items:data.settings[key]||[]},'touchline-'+key+'-'+new Date().toISOString().slice(0,10)+'.json');$(importId).onclick=()=>$(fileId).click();$(fileId).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text()),items=Array.isArray(x)?x:x.items;if(!Array.isArray(items))throw Error();if(!confirm('Import '+label+'? Existing items will be kept and new items added.'))return;data.settings[key]=[...new Set([...(data.settings[key]||[]),...items.map(v=>String(v).trim()).filter(Boolean)])];save();alert(label+' imported.')}catch{alert('Choose a valid '+label+' JSON backup.')}e.target.value=''}}
